<?php use Hls\Http\View as V; ?><section class="panel table-panel"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Cabang</th><th>Nilai</th><th>Dibayar</th><th>Sisa</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): $remain=(float)$r['total_amount']-(float)$r['paid']; ?><tr><td><?= V::escape($r['official_number']) ?></td><td><?= V::escape($r['customer_name']) ?></td><td><?= V::escape($r['branch_name']) ?></td><td><?= \Hls\Http\View::money($r['total_amount']) ?></td><td><?= \Hls\Http\View::money($r['paid']) ?></td><td><?= \Hls\Http\View::money($remain) ?></td><td><?= $remain<=0?'Lunas':($r['paid']>0?'Sebagian':'Belum dibayar') ?></td></tr><?php endforeach ?></tbody></table></section>
